import collections, json, re, sys
tools, near, down, pressure = {}, collections.Counter(), collections.Counter(), collections.Counter()
tilt, buttons, pointer = [0.0, 0.0], set(), 0
for line in open(sys.argv[1], errors='replace'):
    m = re.match(r'\[ *(\d+): *(\w+)\] (\w+):? ?(.*)', line)
    if not m:
        continue
    obj, iface, event, args = m.groups()
    pointer += iface == 'wl_pointer' and event == 'button'
    if iface != 'zwp_tablet_tool_v2':
        continue
    tool = tools.get(obj, obj)
    if event == 'type':
        tools[obj] = args.split('(')[-1].rstrip(')')
    elif event == 'proximity_in':
        near[tool] += 1
    elif event == 'down':
        down[tool] += 1
    elif event == 'pressure':
        pressure[tool] = max(pressure[tool], int(args.split()[0]))
    elif event == 'tilt':
        tilt = [max(t, abs(float(v))) for t, v in zip(tilt, re.findall(r'-?[\d.]+', args))]
    elif event == 'button' and 'state: 1' in args:
        buttons.add(re.search(r'\((\w+)\)', args).group(1))
print(json.dumps({'proximityIn': near, 'down': down, 'maxPressure': pressure, 'maxTilt': tilt,
                  'buttons': sorted(buttons), 'pointerButtons': pointer}))
checks = [('proximity_in', near['pen']), ('pressure', pressure['pen']), ('eraser', near['eraser'])]
print(' '.join('[wayland:%s]' % c for c, n in checks + [('button=' + b, 1) for b in sorted(buttons)] if n))
